head.script:
scwin.GRP_ID = "";
scwin.SEL_PJT_ID = "";

/**
 * 페이지 로드 이벤트 - 수정된 버전
 */
scwin.onpageload = function () {
    // 페이지 로드 시 사이드바를 숨김 상태로 시작
    scwin.hideSidebar();

    // 초기화 완료 후 실행
    setTimeout(function () {
        try {
            tab_content.deleteAllTabs();
            tab_content.addTab("dashboardTab", {
                label: "HOME",
                closable: false,
                openAction: "select"
            }, {
                src: "dashboard.xml",
                frameMode: "wframe"
            });

            // 임시 사용자 관리 탭 추가
            //tab_content.addTab("usersTab", {
            //    label: "사용자 관리",
            //    closable: false,
            //    openAction: "select"
            //}, {
            //    src: "users/UsersList.xml",
            //    frameMode: "wframe"
            //});
        } catch (e) {
            console.error("초기 탭 생성 실패:", e);
            // 실패 시 다시 시도
            scwin.initializeDefaultTab();
        }
    }, 200); // 200ms 후 실행
};

/**
 * 기본 탭 초기화 함수 (재시도 로직 포함)
 */
scwin.initializeDefaultTab = function () {
    var retryCount = 0;
    var maxRetries = 5;

    var tryInitTab = function () {
        try {
            if (tab_content && typeof tab_content.addTab === 'function') {
                tab_content.deleteAllTabs();
                tab_content.addTab("dashboardTab", {
                    label: "HOME",
                    closable: false,
                    openAction: "select"
                }, {
                    src: "dashboard.xml",
                    frameMode: "wframe"
                });
                console.log("기본 탭 초기화 성공");
            } else {
                throw new Error("tab_content가 초기화되지 않음");
            }
        } catch (e) {
            retryCount++;
            if (retryCount < maxRetries) {
                console.log(`탭 초기화 재시도 ${retryCount}/${maxRetries}`);
                setTimeout(tryInitTab, 200 * retryCount); // 점진적 지연
            } else {
                console.error("탭 초기화 최종 실패:", e);
            }
        }
    };

    tryInitTab();
};


/**
 * 사이드바를 보여주는 함수
 */
scwin.showSidebar = function () {
    grp_menu.removeClass("closed");
};

/**
 * 사이드바를 숨기는 함수
 */
scwin.hideSidebar = function () {
    grp_menu.addClass("closed");
};

/**
 * 사이드바를 토글하는 함수 (기존 show/hide 함수 재사용)
 */
scwin.toggleSidebar = function () {
    if (grp_menu.hasClass("closed")) {
        scwin.showSidebar();
    } else {
        scwin.hideSidebar();
    }
};

// 프로젝트 변경시 호출되는 공용 함수
scwin.onProjectChange = function (pjtId, grpId) {
    console.log("헤더로부터 프로젝트 변경 이벤트 발생: pjtId=" + pjtId);

    // 1. 프로젝트 ID 유무에 따라 사이드바 제어
    if (pjtId && pjtId !== "") {
        scwin.showSidebar();
    } else {
        scwin.hideSidebar();
    }

    // 2. 메뉴 목록을 가져오는 서브미션 실행
    scwin.SEL_PJT_ID = pjtId;
    scwin.GRP_ID = grpId ? grpId[0] : "";

    $c.sbm.execute(sbm_selectMenuList, {
        "elData": { "grpId": scwin.GRP_ID }
    });

};

/**
 * 웹스퀘어 Generator를 사용한 메뉴 생성 함수
 */
scwin.createMenuWithGenerator = function () {
    var genObj = gen_menu;
    genObj.removeAll(); // 기존 메뉴 제거

    var menuListLength = dlt_menuVoList.getRowCount();

    // 메뉴 데이터를 그룹화 (1뎁스 기준)
    var menuGroups = {};

    // 1뎁스와 2뎁스 메뉴를 분리하여 그룹화
    for (var i = 0; i < menuListLength; i++) {
        var menuData = dlt_menuVoList.getRowJSON(i);
        var parentId = menuData.parentMenuId || 'root';

        if (parentId === 'root' || parentId === '') {
            // 1뎁스 메뉴인 경우
            if (!menuGroups[menuData.menuId]) {
                menuGroups[menuData.menuId] = {
                    menu: menuData,
                    children: []
                };
            }
        } else {
            // 2뎁스 메뉴인 경우
            if (!menuGroups[parentId]) {
                menuGroups[parentId] = {
                    menu: null,
                    children: []
                };
            }
            menuGroups[parentId].children.push(menuData);
        }
    }

    // 그룹화된 메뉴 데이터로 실제 메뉴 DOM 생성
    for (var groupId in menuGroups) {
        var group = menuGroups[groupId];
        if (group.menu) {
            // 1뎁스 메뉴 생성
            var idx = genObj.insertChild();
            var menuObj = genObj.getChild(idx, "anc_menu");

            // 1뎁스 메뉴 설정
            menuObj.setValue(group.menu.menuName);
            menuObj.setUserData("menuId", group.menu.menuId);
            menuObj.setUserData("menuUrl", group.menu.menuUrl);
            menuObj.setUserData("hasChildren", group.children.length > 0 ? "Y" : "N");

            // 메뉴 전체 영역 클릭 이벤트 추가
            scwin.addMenuClickEvent(menuObj, idx);

            // 2뎁스 메뉴가 있는 경우 하위 메뉴 생성
            if (group.children.length > 0) {
                var subGenObj = genObj.getChild(idx, "gen_subMenu");
                for (var j = 0; j < group.children.length; j++) {
                    var childMenu = group.children[j];
                    var subIdx = subGenObj.insertChild();
                    var subMenuObj = subGenObj.getChild(subIdx, "anc_subMenu");

                    // 2뎁스 메뉴 설정
                    subMenuObj.setValue(childMenu.menuName);
                    subMenuObj.setUserData("menuId", childMenu.menuId);
                    subMenuObj.setUserData("menuUrl", childMenu.menuUrl);
                    subMenuObj.setUserData("parentId", childMenu.parentId);

                    // 서브메뉴 전체 영역 클릭 이벤트 추가
                    scwin.addSubmenuClickEvent(subMenuObj, idx, subIdx);
                }
            }
        }
    }
};

/**
 * 메뉴 전체 영역 클릭 이벤트 추가 (CSS 클래스 유지)
 */
scwin.addMenuClickEvent = function (menuObj, idx) {
    setTimeout(function () {
        var menuElement = document.getElementById(menuObj.getID());
        if (menuElement && menuElement.parentElement) {
            var parentEl = menuElement.parentElement;

            // 기존 클래스 유지하면서 클릭 이벤트만 추가
            parentEl.addEventListener('click', function (e) {
                e.preventDefault();
                e.stopPropagation();
                scwin.menu_onclick.call(menuObj);
            });

            // 커서만 추가 (기존 스타일 유지)
            if (!parentEl.style.cursor) {
                parentEl.style.cursor = 'pointer';
            }
        }
    }, 100);
};

/**
 * 서브메뉴 전체 영역 클릭 이벤트 추가 (CSS 클래스 유지)
 */
scwin.addSubmenuClickEvent = function (subMenuObj, parentIdx, subIdx) {
    setTimeout(function () {
        var submenuElement = document.getElementById(subMenuObj.getID());
        if (submenuElement && submenuElement.parentElement) {
            var parentEl = submenuElement.parentElement;

            // 기존 클래스 유지하면서 클릭 이벤트만 추가
            parentEl.addEventListener('click', function (e) {
                e.preventDefault();
                e.stopPropagation();
                scwin.submenu_onclick.call(subMenuObj);
            });

            // 커서만 추가 (기존 스타일 유지)
            if (!parentEl.style.cursor) {
                parentEl.style.cursor = 'pointer';
            }
        }
    }, 100);
};

/**
 * 1뎁스 메뉴 클릭 이벤트 핸들러
 */
scwin.menu_onclick = function () {
    var hasChildren = this.getUserData("hasChildren");
    var menuUrl = this.getUserData("menuUrl");

    if (hasChildren === "Y") {
        // 하위 메뉴 토글
        scwin.toggleSubMenu(this);
    } else if (menuUrl && menuUrl.trim() !== "") {
        // 단일 페이지 메뉴인 경우 탭으로 열기
        var menuName = this.getValue();
        scwin.openTab(menuUrl, menuName);
    }
};

/**
 * 2뎁스 메뉴 클릭 이벤트 핸들러
 */
scwin.submenu_onclick = function () {
    var menuUrl = this.getUserData("menuUrl");
    var menuName = this.getValue();

    if (menuUrl && menuUrl.trim() !== "") {
        scwin.openTab(menuUrl, menuName);
    }
};

/**
 * 하위 메뉴 토글 함수 (CSS 클래스 활용)
 */
scwin.toggleSubMenu = function (menuObj) {
    var gen = menuObj.getGenerator();
    var idx = menuObj.getGeneratedIndex();
    var subNavObj = gen.getChild(idx, 'gen_subMenu');

    // 다른 모든 하위 메뉴 닫기 (아코디언 효과)
    for (var i = 0; i < gen.getLength(); i++) {
        if (i !== idx) {
            var otherSubNav = gen.getChild(i, 'gen_subMenu');
            otherSubNav.hide();
            otherSubNav.removeClass('submenu-show');
        }
    }

    // 현재 메뉴의 하위 메뉴 토글
    if (subNavObj.getStyle('display') === 'none' || !subNavObj.getStyle('display')) {
        subNavObj.show();
        subNavObj.addClass('submenu-show');
    } else {
        subNavObj.hide();
        subNavObj.removeClass('submenu-show');
    }
};

/**
 * 개선된 탭 열기 함수 (데이터 전달 지원)
 * @param {string} url - 열 페이지 URL
 * @param {string} title - 탭 제목
 * @param {Object} tabData - 전달할 탭 데이터 (선택사항)
 */
// 기존 중복 탭 확인 부분을 다음과 같이 수정:

scwin.openTab = async function (url, title, tabData) {
    var tabId = "tab_" + new Date().getTime();

    try {
        var tabInfo = tab_content.getTabInfo();
        var existingTabId = null;
        var existingTabIndex = -1;

        // 같은 URL의 탭이 이미 열려있는지 확인
        for (var i = 0; i < tabInfo.length; i++) {
            if (tabInfo[i] && tabInfo[i].src === url) {
                existingTabId = tabInfo[i].id;  // 기존 탭 ID 저장
                existingTabIndex = i;
                break;
            }
        }

        // contentOptions 설정
        var contentOptions = {
            "src": url,
            "frameMode": "wframePreload",
            "scope": true,
            "alwaysDraw": true
        };

        if (tabData) {
            contentOptions.dataObject = {
                "type": "json",
                "name": "tabData",
                "data": tabData
            };
        }

        if (existingTabIndex !== -1) {
            // 기존 탭ID로 exist 옵션 사용
            console.log("기존 탭 갱신:", existingTabId);

            var newTabId = await tab_content.addTab(existingTabId, {
                "label": title,
                "closable": true,
                "openAction": "exist"  // 기존 탭 내용을 새로 고침
            }, contentOptions);

            await tab_content.setSelectedTabIndex(existingTabIndex);
        } else {
            // 새 탭인 경우 (기존 로직 유지)
            var newTabId = await tab_content.addTab(tabId, {
                "label": title,
                "closable": true,
                "openAction": "new"
            }, contentOptions);

            await tab_content.setSelectedTabIndex(newTabId);
        }

    } catch (e) {
        console.error("탭 생성 실패:", e);
        $c.win.alert("페이지를 로드할 수 없습니다: " + title);
    }
};

/**
 * 모든 탭 닫기 버튼 클릭 이벤트
 */
scwin.btn_closeAllTabs_onclick = function () {
    try {
        // 현재 열린 탭 개수 확인
        var tabCount = tab_content.getTabCount();

        if (tabCount <= 1) {
            $c.win.alert("닫을 탭이 없습니다.");
            return;
        }

        // 사용자 확인
        var promise = $c.win.confirm("모든 탭을 닫으시겠습니까?\n(HOME 탭은 유지됩니다)")
        promise.then(function (result) {
                if (result) {
                    // 모든 탭 삭제
                    tab_content.deleteAllTabs();

                    // HOME 탭 재생성
                    setTimeout(function () {
                        tab_content.addTab("dashboardTab", {
                            label: "HOME",
                            closable: false,
                            openAction: "select"
                        }, {
                            src: "dashboard.xml",
                            frameMode: "wframe"
                        });

                        console.log("모든 탭 닫기 완료 - HOME 탭 재생성됨");
                    }, 100);
                }
            });

    } catch (e) {
        console.error("모든 탭 닫기 실패:", e);
        $c.win.alert("탭을 닫는 중 오류가 발생했습니다.");
    }
};

// 메뉴조회 콜백
scwin.sbm_selectMenuList_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader === "" || elHeader === "undefined" || elHeader.resSuc === false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    dlt_menuVoList.setJSON(elData.menuVo);
    // 웹스퀘어 Generator를 사용한 동적 메뉴 생성
    scwin.createMenuWithGenerator();

    // 탭 초기화
    tab_content.deleteAllTabs();
    tab_content.addTab("dashboardTab", {
        label: "HOME",
        closable: false,
        openAction: "select"
    }, {
        src: "dashboard.xml",
        frameMode: "wframe"
    });
};
